using System.Collections.Generic;
using Sirenix.OdinInspector;
using UnityEngine;

/// <summary>
/// Player body animation view: a thin, null-safe wrapper over a parameter-driven Animator
/// (2D strafe locomotion + an upper-body layer). Driven every frame by ECS.PlayerAnimationSystem.
/// Unlike <see cref="SimpleAnimator"/> (cross-fade by state name, used by mobs) the player needs
/// blend trees and layers, so it works through Animator parameters.
///
/// The controller is generated by Tools ▸ Crowds ▸ Create Player Animator Controller
/// (parameter names below must match it). A parameter missing from the controller is silently
/// skipped, so a half-filled controller works while clips are being added.
/// See Docs/PlayerAnimation.md.
/// </summary>
[RequireComponent(typeof(Animator))]
// Before WeaponHandIK: the procedural kick moves the arms/spine first, the IK then reaches from the final pose.
[DefaultExecutionOrder(-50)]
public class PlayerAnimator : MonoBehaviour
{
	// Animator parameter names (the controller builder uses the same constants).
	public const string MoveXParam = "MoveX";
	public const string MoveYParam = "MoveY";
	public const string MoveSpeedParam = "MoveSpeed";
	public const string WeaponSetParam = "WeaponSet";
	public const string IsFiringParam = "IsFiring";
	public const string FireParam = "Fire";
	public const string IsReloadingParam = "IsReloading";
	public const string ReloadSpeedParam = "ReloadSpeed";
	public const string MeleeParam = "Melee";
	public const string IsChargingThrowParam = "IsChargingThrow";
	public const string ThrowParam = "Throw";
	public const string HitParam = "Hit";
	public const string IsDeadParam = "IsDead";
	public const string UpperBodyLayer = "UpperBody";

	private static readonly int MoveX = Animator.StringToHash(MoveXParam);
	private static readonly int MoveY = Animator.StringToHash(MoveYParam);
	private static readonly int MoveSpeed = Animator.StringToHash(MoveSpeedParam);
	private static readonly int WeaponSet = Animator.StringToHash(WeaponSetParam);
	private static readonly int IsFiring = Animator.StringToHash(IsFiringParam);
	private static readonly int Fire = Animator.StringToHash(FireParam);
	private static readonly int IsReloading = Animator.StringToHash(IsReloadingParam);
	private static readonly int ReloadSpeed = Animator.StringToHash(ReloadSpeedParam);
	private static readonly int Melee = Animator.StringToHash(MeleeParam);
	private static readonly int IsChargingThrow = Animator.StringToHash(IsChargingThrowParam);
	private static readonly int Throw = Animator.StringToHash(ThrowParam);
	private static readonly int Hit = Animator.StringToHash(HitParam);
	private static readonly int IsDead = Animator.StringToHash(IsDeadParam);

	[BoxGroup("Animator")]
	[SerializeField] private Animator _animator;

	[BoxGroup("Locomotion")]
	[Tooltip("Speed (m/s) the run clips were authored for: at this speed the feet don't slide. " +
	         "Locomotion playback rate = actual speed / this.")]
	[SerializeField, Min(0.1f)] private float _runClipSpeed = 5.5f;
	[BoxGroup("Locomotion")]
	[Tooltip("Smoothing of the MoveX/MoveY blend parameters (sec).")]
	[SerializeField, Min(0f)] private float _moveDamping = 0.1f;

	[BoxGroup("Clip timing")]
	[Tooltip("Length (sec) of the rifle reload clip. Playback speed = this / GunConfig.ReloadTime, " +
	         "so the animation always ends together with the reload.")]
	[SerializeField, Min(0.05f)] private float _rifleReloadClipLength = 2f;
	[BoxGroup("Clip timing")]
	[SerializeField, Min(0.05f)] private float _pistolReloadClipLength = 1.5f;

	[BoxGroup("Weapon models")]
	[Tooltip("Gun meshes attached to the hand bone; the one matching the current animation set is shown. " +
	         "Optional. Visual only — bullets still come from Weapon.Muzzle.")]
	[SerializeField] private GameObject _rifleModel;
	[BoxGroup("Weapon models")]
	[SerializeField] private GameObject _pistolModel;

	[BoxGroup("Weapon models")]
	[Tooltip("Hand bone for per-gun models (GunConfig.Model), e.g. mixamorig:RightHand. Empty = GunConfig models " +
	         "are not shown (only the legacy rifle/pistol models above).")]
	[SerializeField] private Transform _weaponBone;
	[BoxGroup("Weapon models")]
	[Tooltip("Pose of the weapon root (= right-hand grip, barrel +Z) in the hand bone, tuned once in the Aim pose. " +
	         "Position in METRES along the bone axes (bone scale is compensated). " +
	         "Shared by all guns because every WeaponModel uses the same convention.")]
	[SerializeField] private Vector3 _weaponLocalPosition;
	[BoxGroup("Weapon models")]
	[SerializeField] private Vector3 _weaponLocalEuler;
	[BoxGroup("Weapon models")]
	[Tooltip("World scale of the gun model (bone scale is compensated, Mixamo bones are often 0.01).")]
	[SerializeField, Min(0.01f)] private float _weaponScale = 1f;
	[BoxGroup("Weapon models")]
	[Tooltip("Optional left-hand IK on the same body: receives the current gun model as its target.")]
	[SerializeField] private WeaponHandIK _leftHandIK;

	[BoxGroup("Barrel aim")]
	[Tooltip("After the animation the hand bone is turned so the held gun's barrel points exactly where the player " +
	         "faces (the cursor, = bullet direction) and stays upright: the run bob can't swing it off the aim line.")]
	[SerializeField] private bool _aimBarrel = true;
	[BoxGroup("Barrel aim")]
	[Tooltip("UpperBody / base states in which the barrel is NOT forced (the clip moves the gun on purpose).")]
	[SerializeField] private string[] _freeBarrelStates =
		{ "Reload_Rifle", "Reload_Pistol", "Melee", "ThrowCharge", "Throw", "Death" };
	[BoxGroup("Barrel aim")]
	[Tooltip("Blend in/out speed of the barrel lock, weight per second.")]
	[SerializeField, Min(0.1f)] private float _aimBlendSpeed = 8f;

	[BoxGroup("Procedural kicks")]
	[Tooltip("Sets whose Fire clip is missing (the pipeline put the static aim pose there): every shot kicks the arms up " +
	         "procedurally instead. Mixamo has no two-handed pistol fire clip.")]
	[SerializeField] private List<WeaponAnimationSet> _proceduralRecoilSets = new();
	[BoxGroup("Procedural kicks")]
	[Tooltip("Sets whose Hit clip is missing: a hit leans the spine back procedurally.")]
	[SerializeField] private List<WeaponAnimationSet> _proceduralFlinchSets = new();
	[BoxGroup("Procedural kicks")]
	[Tooltip("Recoil: upper arms / hands pitch-up, degrees.")]
	[SerializeField] private Vector2 _recoilAngles = new(7f, 12f);
	[BoxGroup("Procedural kicks")]
	[SerializeField, Min(0.02f)] private float _recoilDuration = 0.15f;
	[BoxGroup("Procedural kicks")]
	[Tooltip("Flinch: spine / chest lean-back, degrees.")]
	[SerializeField] private Vector2 _flinchAngles = new(6f, 8f);
	[BoxGroup("Procedural kicks")]
	[SerializeField, Min(0.02f)] private float _flinchDuration = 0.35f;

	private readonly HashSet<int> _parameters = new();
	private int _upperBodyLayer = -1;
	private bool _isPaused;
	private bool _isDead;
	private WeaponAnimationSet _weaponSet = (WeaponAnimationSet)(-1);
	private readonly Dictionary<GunConfig, WeaponModel> _gunModels = new();
	private GunConfig _gun;
	private WeaponModel _gunModel;
	private float _recoilTime = float.MaxValue;
	private float _flinchTime = float.MaxValue;
	private Transform _rUpperArm, _lUpperArm, _rHand, _lHand, _spine, _chest;
	private readonly HashSet<int> _freeBarrelHashes = new();
	private float _aimWeight;

	public Animator Animator => _animator;
	/// <summary>The gun model shown in the hand right now (GunConfig.Model), or null.</summary>
	public WeaponModel CurrentGunModel => _gunModel != null && _gunModel.gameObject.activeInHierarchy ? _gunModel : null;

	private void Awake()
	{
		if (_animator == null)
			_animator = GetComponent<Animator>();
		CacheParameters();
		foreach (var state in _freeBarrelStates)
			if (!string.IsNullOrEmpty(state))
				_freeBarrelHashes.Add(Animator.StringToHash(state));
		if (_animator != null && _animator.isHuman)
		{
			_rUpperArm = _animator.GetBoneTransform(HumanBodyBones.RightUpperArm);
			_lUpperArm = _animator.GetBoneTransform(HumanBodyBones.LeftUpperArm);
			_rHand = _animator.GetBoneTransform(HumanBodyBones.RightHand);
			_lHand = _animator.GetBoneTransform(HumanBodyBones.LeftHand);
			_spine = _animator.GetBoneTransform(HumanBodyBones.Spine);
			_chest = _animator.GetBoneTransform(HumanBodyBones.Chest);
		}
	}

	/// <summary>
	/// Procedural recoil / flinch on top of the animated pose for sets that have no such clip. Both kicks rotate
	/// about the body's right axis (negative = up / back), so the two-handed grip stays together.
	/// </summary>
	private void LateUpdate()
	{
		if (_isDead)
			return;
		// Paused: the kicks freeze (no time advance), the barrel lock still applies (the animator keeps writing the pose).
		float dt = _isPaused ? 0f : Time.deltaTime;
		var axis = transform.right;

		_recoilTime += dt;
		float r = Kick(_recoilTime, _recoilDuration);
		if (r > 0f)
		{
			Rotate(_rUpperArm, axis, -_recoilAngles.x * r);
			Rotate(_lUpperArm, axis, -_recoilAngles.x * r);
			Rotate(_rHand, axis, -_recoilAngles.y * r);
			Rotate(_lHand, axis, -_recoilAngles.y * r);
		}

		_flinchTime += dt;
		float f = Kick(_flinchTime, _flinchDuration);
		if (f > 0f)
		{
			Rotate(_spine, axis, -_flinchAngles.x * f);
			Rotate(_chest, axis, -_flinchAngles.y * f);
		}

		AimBarrel(r, _isPaused ? 0f : Time.deltaTime);
	}

	/// <summary>
	/// Turns the weapon bone so the gun model looks along the body's forward (the player faces the cursor, bullets
	/// fly along it) with its top up. The gun is a child of the bone, so the hand and the left-hand IK target
	/// (WeaponHandIK runs after this) follow. The procedural recoil pitch is re-applied on top.
	/// </summary>
	private void AimBarrel(float recoil, float dt)
	{
		bool active = _aimBarrel && _weaponBone != null && _gunModel != null && _gunModel.gameObject.activeInHierarchy;
		float wanted = active && !IsInFreeBarrelState() ? 1f : 0f;
		_aimWeight = dt > 0f ? Mathf.MoveTowards(_aimWeight, wanted, _aimBlendSpeed * dt) : (wanted <= 0f ? 0f : _aimWeight);
		if (!active || _aimWeight <= 0.001f)
			return;

		var gun = _gunModel.transform;
		var desired = Quaternion.LookRotation(transform.forward, Vector3.up);
		if (recoil > 0f && _proceduralRecoilSets.Contains(_weaponSet))
			desired = Quaternion.AngleAxis(-(_recoilAngles.x + _recoilAngles.y) * recoil, transform.right) * desired;
		var delta = Quaternion.Slerp(Quaternion.identity, desired * Quaternion.Inverse(gun.rotation), _aimWeight);
		_weaponBone.rotation = delta * _weaponBone.rotation;
	}

	private bool IsInFreeBarrelState()
	{
		if (_animator == null || _freeBarrelHashes.Count == 0)
			return false;
		bool Check(int layer)
		{
			if (layer < 0 || layer >= _animator.layerCount) return false;
			var info = _animator.IsInTransition(layer) ? _animator.GetNextAnimatorStateInfo(layer) : _animator.GetCurrentAnimatorStateInfo(layer);
			return _freeBarrelHashes.Contains(info.shortNameHash);
		}
		return Check(0) || Check(_upperBodyLayer);
	}

	/// <summary>0→1 in the first 20% (snap), then eases back to 0 by <paramref name="duration"/>.</summary>
	private static float Kick(float t, float duration)
	{
		if (t >= duration) return 0f;
		float rise = duration * 0.2f;
		if (t < rise) return t / rise;
		float k = 1f - (t - rise) / (duration - rise);
		return k * k * (3f - 2f * k);
	}

	private static void Rotate(Transform bone, Vector3 axis, float degrees)
	{
		if (bone != null) bone.rotation = Quaternion.AngleAxis(degrees, axis) * bone.rotation;
	}

	private void CacheParameters()
	{
		_parameters.Clear();
		if (_animator == null || _animator.runtimeAnimatorController == null)
			return;
		foreach (var p in _animator.parameters)
			_parameters.Add(p.nameHash);
		_upperBodyLayer = _animator.GetLayerIndex(UpperBodyLayer);
	}

	private bool Has(int hash) => _animator != null && _parameters.Contains(hash);

	/// <param name="localMove">Move direction in the player's local space (x = strafe, y = forward), length 0..1.</param>
	/// <param name="speed">Actual movement speed, m/s (0 when standing).</param>
	public void SetLocomotion(Vector2 localMove, float speed)
	{
		if (Has(MoveX)) _animator.SetFloat(MoveX, localMove.x, _moveDamping, Time.deltaTime);
		if (Has(MoveY)) _animator.SetFloat(MoveY, localMove.y, _moveDamping, Time.deltaTime);
		// Standing: play idle at normal rate (0 would freeze it).
		if (Has(MoveSpeed)) _animator.SetFloat(MoveSpeed, speed > 0.01f ? speed / _runClipSpeed : 1f);
	}

	public void SetWeaponSet(WeaponAnimationSet set)
	{
		if (set == _weaponSet)
			return;
		_weaponSet = set;
		if (Has(WeaponSet)) _animator.SetInteger(WeaponSet, (int)set);
		if (_rifleModel != null) _rifleModel.SetActive(set == WeaponAnimationSet.Rifle);
		if (_pistolModel != null) _pistolModel.SetActive(set == WeaponAnimationSet.Pistol);
	}

	/// <summary>
	/// Current gun: switches the animation set and shows the gun's own model (GunConfig.Model) in the hand bone.
	/// Models are instantiated once per config and then toggled.
	/// </summary>
	public void SetWeapon(GunConfig gun)
	{
		if (gun == null)
			return;
		SetWeaponSet(gun.AnimationSet);
		if (gun == _gun)
			return;
		_gun = gun;

		if (_gunModel != null)
		{
			_gunModel.SetMagazineVisible(true);
			_gunModel.gameObject.SetActive(false);
		}
		_gunModel = GetOrCreateModel(gun);
		if (_gunModel != null)
		{
			_gunModel.gameObject.SetActive(true);
			// A per-gun model replaces the legacy set models.
			if (_rifleModel != null) _rifleModel.SetActive(false);
			if (_pistolModel != null) _pistolModel.SetActive(false);
		}
		else
		{
			if (_rifleModel != null) _rifleModel.SetActive(_weaponSet == WeaponAnimationSet.Rifle);
			if (_pistolModel != null) _pistolModel.SetActive(_weaponSet == WeaponAnimationSet.Pistol);
		}
		if (_leftHandIK != null)
			_leftHandIK.SetWeapon(_gunModel);
	}

	private WeaponModel GetOrCreateModel(GunConfig gun)
	{
		if (gun.Model == null || _weaponBone == null)
			return null;
		if (_gunModels.TryGetValue(gun, out var model) && model != null)
			return model;

		model = Instantiate(gun.Model, _weaponBone);
		var t = model.transform;
		float boneScale = Mathf.Max(_weaponBone.lossyScale.x, 1e-4f);
		// Position is authored in metres: convert to bone units (Mixamo bones are often scaled 0.01).
		t.SetLocalPositionAndRotation(_weaponLocalPosition / boneScale, Quaternion.Euler(_weaponLocalEuler));
		t.localScale = Vector3.one * (_weaponScale / boneScale);
		_gunModels[gun] = model;
		return model;
	}

	public void SetFiring(bool firing)
	{
		if (Has(IsFiring)) _animator.SetBool(IsFiring, firing);
	}

	/// <summary>One shot left the muzzle (recoil kick).</summary>
	public void TriggerFire()
	{
		if (Has(Fire)) _animator.SetTrigger(Fire);
		if (_proceduralRecoilSets.Contains(_weaponSet)) _recoilTime = 0f;
	}

	/// <param name="gunReloadTime">GunConfig.ReloadTime — the clip is time-scaled to it.</param>
	public void SetReloading(bool reloading, float gunReloadTime)
	{
		if (Has(IsReloading)) _animator.SetBool(IsReloading, reloading);
		// The magazine is "out" during the whole reload (SMG/AR/MG have it visible outside).
		if (_gunModel != null) _gunModel.SetMagazineVisible(!reloading);
		if (reloading && Has(ReloadSpeed) && gunReloadTime > 0.01f)
		{
			float clip = _weaponSet == WeaponAnimationSet.Pistol ? _pistolReloadClipLength : _rifleReloadClipLength;
			_animator.SetFloat(ReloadSpeed, clip / gunReloadTime);
		}
	}

	public void TriggerMelee()
	{
		if (Has(Melee)) _animator.SetTrigger(Melee);
	}

	public void SetChargingThrow(bool charging)
	{
		if (Has(IsChargingThrow)) _animator.SetBool(IsChargingThrow, charging);
	}

	public void TriggerThrow()
	{
		if (Has(Throw)) _animator.SetTrigger(Throw);
	}

	public void TriggerHit()
	{
		if (Has(Hit)) _animator.SetTrigger(Hit);
		// The Hit state is entered only from aim, so a reload/throw isn't shaken either.
		if (_proceduralFlinchSets.Contains(_weaponSet) && !IsReloadingNow()) _flinchTime = 0f;
	}

	private bool IsReloadingNow() => Has(IsReloading) && _animator.GetBool(IsReloading);

	/// <summary>Death: full-body death clip, the upper-body layer is faded out so it can't override it.</summary>
	public void SetDead(bool dead)
	{
		if (_isDead == dead)
			return;
		_isDead = dead;
		if (Has(IsDead)) _animator.SetBool(IsDead, dead);
		if (_animator != null && _upperBodyLayer >= 0)
			_animator.SetLayerWeight(_upperBodyLayer, dead ? 0f : 1f);
	}

	/// <summary>Game pause is a flag (timeScale stays 1), so the Animator has to be frozen explicitly.</summary>
	public void SetPaused(bool paused)
	{
		if (_isPaused == paused || _animator == null)
			return;
		_isPaused = paused;
		_animator.speed = paused ? 0f : 1f;
	}
}
